import re


class StackUnderflowError(Exception):
    pass


_NUMBER_RE = re.compile(r"-?\d+")


def _is_number(token):
    return bool(_NUMBER_RE.fullmatch(token))


def _pop(stack):
    if not stack:
        raise StackUnderflowError("Insufficient number of items in stack")
    return stack.pop()


def _add(stack):
    b = _pop(stack)
    a = _pop(stack)
    stack.append(a + b)


def _sub(stack):
    b = _pop(stack)
    a = _pop(stack)
    stack.append(a - b)


def _mul(stack):
    b = _pop(stack)
    a = _pop(stack)
    stack.append(a * b)


def _div(stack):
    b = _pop(stack)
    a = _pop(stack)
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    quotient = a // b
    # Truncate toward zero, like Forth, instead of flooring.
    if a % b != 0 and (a < 0) != (b < 0):
        quotient += 1
    stack.append(quotient)


def _dup(stack):
    stack.append(_pop(stack))


def _drop(stack):
    _pop(stack)


def _swap(stack):
    b = _pop(stack)
    a = _pop(stack)
    stack.append(b)
    stack.append(a)


def _over(stack):
    b = _pop(stack)
    a = _pop(stack)
    stack.append(a)
    stack.append(b)
    stack.append(a)


_BUILTINS = {
    "+": _add,
    "-": _sub,
    "*": _mul,
    "/": _div,
    "dup": _dup,
    "drop": _drop,
    "swap": _swap,
    "over": _over,
}


def _run(actions, stack):
    for kind, value in actions:
        if kind == "num":
            stack.append(value)
        else:
            value(stack)


def _make_word(actions):
    def word(stack):
        _run(actions, stack)

    return word


def _resolve(token, words):
    """Resolve a word token to an action, or return None for numbers."""
    if _is_number(token):
        return ("num", int(token))
    name = token.lower()
    if name in words:
        return ("word", words[name])
    if name in _BUILTINS:
        return ("word", _BUILTINS[name])
    raise ValueError("undefined operation")


def evaluate(input_data):
    stack = []
    words = {}
    for line in input_data:
        tokens = line.split()
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token == ":":
                name = tokens[i + 1].lower()
                if _is_number(name):
                    raise ValueError("illegal operation")
                j = i + 2
                actions = []
                while tokens[j] != ";":
                    actions.append(_resolve(tokens[j], words))
                    j += 1
                words[name] = _make_word(actions)
                i = j + 1
            else:
                _run([_resolve(token, words)], stack)
                i += 1
    return stack

